using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public class PW {
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr dc, uint flags);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb, IntPtr p);
  public delegate bool EnumProc(IntPtr h, IntPtr p);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }

  public static List<IntPtr> TopLevel(uint want) {
    var found = new List<IntPtr>();
    EnumWindows(delegate(IntPtr h, IntPtr p) {
      uint pid; GetWindowThreadProcessId(h, out pid);
      if (pid == want && IsWindowVisible(h)) found.Add(h);
      return true;
    }, IntPtr.Zero);
    return found;
  }
}
"@

$procs = Get-Process $ProcName -ErrorAction SilentlyContinue
if (-not $procs) { Write-Output "NO PROCESS $ProcName"; exit 1 }
$pid0 = $procs[0].Id

$wins = [PW]::TopLevel([uint32]$pid0)
Write-Output "windows=$($wins.Count)"
$i = 0
foreach ($h in $wins) {
  $r = New-Object PW+RECT
  [void][PW]::GetWindowRect($h, [ref]$r)
  $w = $r.Right - $r.Left; $ht = $r.Bottom - $r.Top
  if ($w -le 8 -or $ht -le 8) { continue }
  $cls = New-Object System.Text.StringBuilder 256
  [void][PW]::GetClassNameW($h, $cls, 256)
  $bmp = New-Object System.Drawing.Bitmap $w, $ht
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $dc = $g.GetHdc()
  $ok = [PW]::PrintWindow($h, $dc, 2)   # PW_RENDERFULLCONTENT
  $g.ReleaseHdc($dc)
  $path = Join-Path $OutDir ("{0}-{1}.png" -f $Tag, $i)
  $bmp.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
  $g.Dispose(); $bmp.Dispose()
  Write-Output ("  {0} {1}x{2} ok={3} cls={4} -> {5}" -f $i, $w, $ht, $ok, $cls.ToString(), $path)
  $i++
}

