Add-Type @"
using System;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public class K {
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc cb, IntPtr p);
  [DllImport("user32.dll")] public static extern bool EnumChildWindows(IntPtr h, EnumProc cb, IntPtr p);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern int GetClassNameW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern IntPtr SendMessageW(IntPtr h, uint m, IntPtr w, IntPtr l);
  [DllImport("user32.dll")] public static extern bool PostMessageW(IntPtr h, uint m, IntPtr w, IntPtr l);
  public delegate bool EnumProc(IntPtr h, IntPtr p);
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }

  public static List<IntPtr> Roots(uint want) {
    var f = new List<IntPtr>();
    EnumWindows(delegate(IntPtr h, IntPtr p) {
      uint pid; GetWindowThreadProcessId(h, out pid);
      if (pid == want && IsWindowVisible(h)) f.Add(h);
      return true;
    }, IntPtr.Zero);
    return f;
  }
  public static List<IntPtr> Kids(IntPtr root) {
    var f = new List<IntPtr>();
    EnumChildWindows(root, delegate(IntPtr h, IntPtr p) { if (IsWindowVisible(h)) f.Add(h); return true; }, IntPtr.Zero);
    return f;
  }
  public static string Text(IntPtr h) { var s = new StringBuilder(512); GetWindowTextW(h, s, 512); return s.ToString(); }
  public static string Cls(IntPtr h) { var s = new StringBuilder(256); GetClassNameW(h, s, 256); return s.ToString(); }
}
"@

$p = Get-Process $ProcName -ErrorAction SilentlyContinue | Select-Object -First 1
if (-not $p) { Write-Output "NO PROCESS"; exit 1 }
foreach ($root in [K]::Roots([uint32]$p.Id)) {
  Write-Output "ROOT $root '$([K]::Text($root))' cls=$([K]::Cls($root))"
  $n = 0
  foreach ($k in [K]::Kids($root)) {
    $r = New-Object K+RECT; [void][K]::GetWindowRect($k, [ref]$r)
    $t = [K]::Text($k)
    Write-Output ("   [{0}] {1} {2},{3} {4}x{5} cls={6} txt='{7}'" -f $n, $k, $r.Left, $r.Top, ($r.Right-$r.Left), ($r.Bottom-$r.Top), [K]::Cls($k), $t)
    $n++
    if ($n -gt 60) { Write-Output "   ..."; break }
  }
}

